var zoom = 1000;
var verticesNum = 400;
var rotateSpeed = 0.005;

setup = () => {
    createCanvas(800, 800);
};

draw = () => {
    background(16);
    translate(width / 2, height / 2);

    vertices.spawn();
    vertices.update();
    vertices.show();
    vertices.generateConnections();
    vertices.drawConnections();
};

mouseClicked = () => {
    vertices.clear();
};

var vtx = () => ({
    alpha: random(TWO_PI),
    beta: random(TWO_PI),
    x: 0,
    y: 0,
    z: 0,

    update() {
        this.beta += rotateSpeed;
        this.x = sin(this.alpha) * cos(this.beta);
        this.y = cos(this.alpha);
        this.z = sin(this.alpha) * sin(this.beta);
    },
});

var vertices = {
    vertices: [],
    connectionCache: [],

    clear() {
        this.vertices.length = 0;
        this.connectionCache.length = 0;
    },

    spawn() {
        if (frameCount % 10 != 0) return;
        if (this.vertices.length < verticesNum) {
            this.vertices.push(vtx());
            this.connectionCache.length = 0; // Reset cache when new vertex spawns
        }
    },

    generateConnections() {
        if (this.connectionCache.length > 0) return;

        for (let i = this.vertices.length; i--;) {
            const current = this.vertices[i];
            for (let j = i; j--;) {
                const other = this.vertices[j];
                const d = this.dist2(other, current);
                if (
                    !this.vertices.some(
                        (any) => d > this.dist2(current, any) && d > this.dist2(other, any)
                    )
                ) {
                    this.connectionCache.push({ current, other });
                }
            }
        }
    },

    drawConnections() {
        stroke('white');
        for (let i = 0; i < this.connectionCache.length; i++) {
            const conn = this.connectionCache[i];
            const current = conn.current;
            const other = conn.other;

            const z1 = 3 - current.z;
            const x1 = current.x / z1;
            const y1 = current.y / z1;

            const z2 = 3 - other.z;
            const x2 = other.x / z2;
            const y2 = other.y / z2;

            strokeWeight(10 / (z1 + z2));
            stroke(255, map(z1 + z2, 4, 8, 333, 80));
            line(x1 * zoom, y1 * zoom, x2 * zoom, y2 * zoom);
        }
    },

    dist2(a, b) {
        return (a.x - b.x) ** 2 + (a.y - b.y) ** 2 + (a.z - b.z) ** 2;
    },

    update() {
        this.vertices.forEach((v) => v.update());
    },

    show() {
        return;
        fill(255);
        noStroke();
        for (const v of this.vertices) {
            const z = 3 - v.z;
            const x = v.x / z;
            const y = v.y / z;
            ellipse(x * zoom, y * zoom, 30 / z);
        }
    },
};
